<?php foreach($conversation as $letter):$author=alphano_mail_person((int)$letter['idmittente'],$mailPeople);$mine=(int)$letter['idmittente']===$idpg;$letterKind=alphano_mail_kind($letter);$letterPortrait=$letterKind==='personal'?($author['portrait']?:alphano_mail_artwork('system')):alphano_mail_artwork($letterKind);$letterBody=(string)$letter['messaggio'];if((int)$letter['idmittente']===0)$letterBody=preg_replace('/\[alphano-trade:\d+:\d+\]/','',$letterBody);$parts=alphano_mail_bubble_parts($letterBody); ?>
<article class="mw-message <?=$mine?'mw-own':'mw-received'?> mw-kind-<?=$h($letterKind)?>" id="mw-letter-<?=(int)$letter['id']?>" data-letter="<?=(int)$letter['id']?>">
<?php if(!$mine): ?><img class="mw-message-avatar" src="<?=$h($letterPortrait)?>" alt="<?=$h($author['name'])?>"><?php endif; ?>
<div class="mw-bubble"><header><strong><?=$h($author['name'])?></strong><small><?=$h($letter['oggetto'])?></small></header><div class="mw-message-text"><?=$parts['body']?></div><footer class="mw-signature"><?=$parts['signature']?></footer><?php if($parts['history']!==''&&count($conversation)===1): ?><details class="mw-quote"><summary>Corrispondenza allegata</summary><?=$parts['history']?></details><?php endif; ?><div class="mw-message-meta"><time datetime="<?=date('c',(int)$letter['data'])?>"><?=$h(date('d/m H:i',(int)$letter['data']))?></time><?php if($mine): ?><span aria-label="<?=$letter['letto']?'Letta':'Inviata'?>"><?=$letter['letto']?'✓✓':'✓'?></span><?php endif; ?><button type="button" data-mw-delete="<?=(int)$letter['id']?>" aria-label="Elimina questa missiva">Elimina</button><?php if((int)$letter['idmittente']>0): ?><button type="button" data-mw-quote="<?=(int)$letter['id']?>">Rispondi</button><?php endif; ?><?php if(!$mine): ?><button type="button" data-mw-archive="<?=(int)$letter['id']?>"><?=$letter['baule']?'Estrai dal baule':'Archivia'?></button><?php endif; ?></div></div>
<?php if($mine): ?><img class="mw-message-avatar" src="<?=$h($letterPortrait)?>" alt="<?=$h($author['name'])?>"><?php endif; ?></article>
<?php endforeach; ?>
